'use strict';
const groups = [{"id": "centro", "number": "01", "title": "Centro e Santo Domingo", "timing": "PICCOLE USCITE DURANTE TUTTO IL VIAGGIO", "color": "pink", "description": "Comincia vicino a casa. Una passeggiata, una chiesa e un pranzo lungo bastano per una giornata.", "sections": [["UN PO’ DI GIRI", [["alcala", "Andador Macedonio Alcalá", "via pedonale da Santo Domingo allo Zócalo"], ["zocalo", "Zócalo e Cattedrale", "piazza principale all’ombra, perfetta per guardare la gente"], ["santodomingo", "Templo de Santo Domingo", "chiesa barocca con interni scolpiti e dorati"], ["culturas", "Museo de las Culturas de Oaxaca", "storia della regione nell’ex convento accanto"], ["jardin", "Jardín Etnobotánico", "giardino di piante native e cactus", "Solo visite guidate: controlla gli orari."]]], ["MANGIARE E PRENDERSELA COMODA", [["brujula", "Café Brújula", "torrefazione locale per una mattina lenta"], ["tlayuda", "Una tlayuda", "enorme tortilla croccante dalla griglia di strada"], ["mayordomo", "Cioccolata da Mayordomo", "cioccolato macinato a pietra, con pan de yema"], ["mole", "Mole negro a Las Quince Letras", "quello scuro al cioccolato per cui Oaxaca è famosa", "Dalla nostra lista salvata. Per un pranzo lungo."]]]], "note": "Una cosa principale e un pasto possono bastare."}, {"id": "muertos", "number": "02", "title": "Día de Muertos", "timing": "LE NOTTI GRANDI", "color": "blue", "description": "Altari, bande e cimiteri a lume di candela. Il motivo per cui siamo qui proprio adesso.", "sections": [["ALTARI E SFILATE", [["abastos", "Mercado de Abastos", "enorme mercato pieno di cempasúchil, teschi di zucchero e pan de muerto"], ["altars", "Altari in centro", "ofrendas pubbliche in chiese, piazze e vetrine"], ["comparsas", "Comparsas", "sfilate in costume con le bande", "La sera, segui la musica."]]], ["LA NOTTE NEI CIMITERI", [["panteon", "Panteón General", "il cimitero della città, decorato per l’occasione"], ["xoxo", "Veglia al cimitero di Xoxocotlán", "le famiglie vegliano a lume di candela sulle tombe", "A circa 8 km: vai con una navetta o un tour organizzato."]]]], "note": "Le notti nei cimiteri sono l’1 e il 2 novembre. Il giorno dopo tienilo completamente libero."}, {"id": "markets", "number": "03", "title": "Mercati e Jalatlaco", "timing": "DUE POMERIGGI TRANQUILLI", "color": "green", "description": "Fumo, cioccolato e vicoli acciottolati. Vieni affamata.", "sections": [["UN POMERIGGIO", [["veinte", "Mercado 20 de Noviembre", "il Pasillo de Humo: scegli la carne e te la grigliano"], ["juarezmkt", "Mercado Benito Juárez", "cioccolato, formaggi, mezcal e chapulines"]]], ["UN ALTRO POMERIGGIO", [["jalatlaco", "Barrio de Jalatlaco", "vicoli acciottolati, murales e piccoli caffè"], ["mezcaloteca", "Mezcaloteca", "degustazione guidata di mezcal artigianali", "Prenota."], ["fortin", "Cerro del Fortín", "collina sopra la città per il tramonto"]]]], "note": "I mercati sono più pieni all’ora di pranzo, ed è proprio il bello."}, {"id": "cooking", "number": "04", "title": "Un corso di cucina", "timing": "UNA MATTINA", "color": "yellow", "description": "Fare la spesa al mercato con una cuoca, poi cucinare tutto da zero.", "sections": [["DAL MERCATO ALLA TAVOLA", [["class", "Mercato e corso di cucina", "salse, tortillas e un mole", "Prenota."]]]], "note": "Il pranzo è quello che cucini, quindi salta la colazione."}, {"id": "food", "number": "05", "title": "Cibo e drink", "timing": "DALLA NOSTRA LISTA SALVATA", "color": "green", "description": "I posti che abbiamo salvato prima di partire. Uno al giorno basta.", "sections": [["COLAZIONE E PANE", [["boulenc", "Boulenc", "panetteria e brunch a Jalatlaco"], ["bodaega", "Bodæga", "piccolo forno artigianale su Hidalgo"]]], ["PRANZI E CENE LUNGHE", [["levadura", "Levadura de Olla", "la cucina oaxaqueña di casa di Thalía Barrios", "Prenota."], ["humo", "La Cocina de Humo", "il suo menù degustazione cotto sul fuoco a legna", "Prenota con largo anticipo."], ["danzantes", "Los Danzantes", "cucina oaxaqueña contemporanea in un cortile aperto"], ["tierrasol", "Tierra del Sol", "cucina mixteca su una terrazza"], ["copal", "Copal", "ristorante su Alcalá, sopra Santo Domingo"]]], ["UN DRINK LA SERA", [["selva", "Selva", "cocktail con ingredienti di Oaxaca"]]]], "note": "Abbina una cena alla passeggiata più vicina."}, {"id": "montealban", "number": "★", "title": "Monte Albán", "timing": "MEZZA GIORNATA FUORI", "color": "yellow", "description": "Una città zapoteca su una collina spianata sopra la valle.", "sections": [["UNA MATTINA FUORI", [["alban", "Monte Albán", "rovine, piazze e una vista ampia sulla valle", "Vai presto: c’è pochissima ombra."], ["arrazola", "San Antonio Arrazola", "paese vicino degli alebrijes, animali di legno dipinti"]]]], "note": "Di ritorno in città per un pranzo tardi.", "weekend": true}, {"id": "hierve", "number": "★", "title": "Hierve el Agua e Mitla", "timing": "UNA GIORNATA INTERA FUORI", "color": "blue", "description": "Cascate pietrificate, rovine scolpite e una distilleria di mezcal, con un tour o un autista.", "sections": [["TUTTA LA GIORNATA, CON CALMA", [["tule", "Árbol del Tule", "uno degli alberi più larghi del mondo"], ["mitla", "Mitla", "rovine coperte di greche di pietra"], ["palenque", "Un palenque di mezcal", "distilleria di famiglia dalle parti di Santiago Matatlán"], ["hierve", "Hierve el Agua", "cascate pietrificate e pozze minerali a picco", "A volte chiude senza preavviso: controlla la settimana prima."]]]], "note": "Una giornata lunga. Tieni libera quella dopo.", "weekend": true}, {"id": "tlacolula", "number": "+", "title": "Tlacolula e Teotitlán", "timing": "UN’USCITA DI DOMENICA", "color": "pink", "description": "Il grande mercato della domenica, poi un paese di tessitori lì vicino.", "sections": [["DI DOMENICA", [["tlacolula", "Mercato di Tlacolula", "uno dei più grandi mercati settimanali della valle", "Solo la domenica."], ["barbacoa", "Barbacoa a pranzo", "capra o agnello cotti lentamente al mercato"], ["teotitlan", "Teotitlán del Valle", "tappeti fatti su telai di legno"]]]], "note": "Porta contanti."}];
const optional = [["tilcajete", "San Martín Tilcajete", "un altro paese di alebrijes, a sud della città"], ["temazcal", "Un temazcal", "il bagno di vapore tradizionale, per un pomeriggio di pioggia"], ["tejate", "Tejate", "bevanda fredda di mais e cacao dai mercati"], ["chapulines", "Chapulines", "cavallette tostate con lime e peperoncino, se hai coraggio"]];
const KEY='frolicking-nicky-oaxaca-v2';
let checked={}; let storageOK=true;
try { const saved=JSON.parse(localStorage.getItem(KEY)||'{}'); if(saved && typeof saved==='object' && !Array.isArray(saved)) checked=saved; } catch {storageOK=false;}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function item(row,extra=false) {const [id,title,desc,note]=row;return `<label class="task${checked[id]===true?' completed':''}"><input type="checkbox" id="${esc(id)}" data-extra="${extra}" ${checked[id]===true?'checked':''}><span class="checkmark" aria-hidden="true"></span><span class="task-copy"><span class="task-title">${esc(title)}</span> <span class="specialty">(${esc(desc)})</span>${note?`<span class="task-note">${esc(note)}</span>`:''}</span></label>`;}
const PHOTOS={"centro": [[["/assets/oax-alcala.jpeg", "Case coloniali colorate lungo l’Andador Macedonio Alcalá", 1400, 1400, "Zitenshi", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Macedonio_de_Alcal%C3%A1.jpg"], ["/assets/oax-jardin.jpeg", "Alti cactus a canne d’organo nel Jardín Etnobotánico accanto all’ex convento", 1400, 1050, "Kaldari", "CC0", "https://commons.wikimedia.org/wiki/File:Jard%C3%ADn_Etnobot%C3%A1nico_de_Oaxaca_06.JPG"]], [["/assets/oax-tlayuda.jpeg", "Una tlayuda con carne, avocado e cipollotti alla griglia", 1400, 1050, "Gomez.erick", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:TLAYUDA.jpg"], ["/assets/oax-chocolate.jpeg", "Il cacao macinato nei molinos di una bottega di cioccolato Mayordomo", 930, 1400, "LBM1948", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Oaxaca_de_Ju%C3%A1rez,_23.jpg"]]], "muertos": [[["/assets/oax-altar.jpeg", "Un altare del Día de Muertos carico di cempasúchil, candele, frutta e fotografie", 1400, 1050, "Jmillan325", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Altar_de_D%C3%ADa_de_Muertos_en_el_Tule_Oaxaca.jpg"], ["/assets/oax-comparsa.jpeg", "Ballerini in costume con sonagli alle gambe in una comparsa del Día de Muertos", 933, 1400, "David Cabrera", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Cascabeles.jpg"]], [["/assets/oax-xoxo.jpeg", "Famiglie in veglia tra le tombe illuminate dalle candele al cimitero di Xoxocotlán", 1400, 933, "Pedro Daniel Godínez Corona", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Velando_en_el_Pante%C3%B3n_de_Xoxocotl%C3%A1n.jpg"]]], "markets": [[["/assets/oax-mercado.jpeg", "Il fumo delle griglie nel corridoio della carne del Mercado 20 de Noviembre", 1400, 937, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mercado_20_de_noviembre_-_Oaxaca_de_Ju%C3%A1rez_-_10.jpg"]], []], "cooking": [[["/assets/oax-mole.jpeg", "Un piatto di mole negro con riso", 1400, 1050, "ProtoplasmaKid", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Mole_negro_de_Oaxaca_con_arroz.jpg"]]], "montealban": [[["/assets/oax-montealban.jpeg", "La Gran Plaza di Monte Albán sulla cima spianata della collina sopra la valle", 1400, 1060, "Infrogmation", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Monte_Alb%C3%A1n_Oaxaca_1976_01.jpg"]]], "hierve": [[["/assets/oax-hierve.jpeg", "La cascata pietrificata e bianca di Hierve el Agua lungo un versante verde", 1400, 1050, "Adrián Cerón", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Hierve_el_agua.JPG"], ["/assets/oax-mitla.jpeg", "Muri decorati a greche di pietra intorno a un cortile a Mitla", 1400, 933, "DavidConFran", "CC BY-SA 3.0", "https://commons.wikimedia.org/wiki/File:Patio_Grupo_Norte.JPG"]]], "tlacolula": [[["/assets/oax-tlacolula.jpeg", "Bancarelle di frutta, fiori e pane al mercato domenicale di Tlacolula", 1400, 933, "Bluerasberry", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlacolula_Market_230122_62.jpg"], ["/assets/oax-teotitlan.jpeg", "Un tessitore al telaio di legno a Teotitlán del Valle, con i tappeti finiti alle spalle", 1280, 854, "Axel Alvarado Chávez", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tejido_de_Tapetes_Artesanales_en_Telar._Teotitl%C3%A1n_Del_Valle,_Oaxaca.jpg"]]], "food": [[], [["/assets/oax-fire.jpeg", "Una donna mescola un grande pentolone di mole sul fuoco a legna", 1050, 1400, "Diego Emiliano Jaramillo Navarro", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Do%C3%B1a_Mari,_la_Reina_del_Mole.jpg"], ["/assets/oax-tlayuda-grill.jpeg", "Un venditore di tlayudas alla griglia per strada, di sera a Oaxaca", 787, 1400, "Alex Haulman", "CC BY-SA 4.0", "https://commons.wikimedia.org/wiki/File:Tlayuda_vendor_in_Oaxaca_City.jpg"]], []]};
const fig=([src,alt,w,h,by,lic,url])=>`<figure class="fn-v-photo"><a href="${src}" target="_blank" rel="noopener"><img src="${src}" alt="${esc(alt)}" width="${w}" height="${h}" loading="lazy"></a>${by?`<figcaption>Foto: ${by} · <a href="${url}" target="_blank" rel="noopener noreferrer">${lic}</a></figcaption>`:''}</figure>`;
let rowN=0;
document.querySelector('#itinerary').innerHTML=groups.map(g=>`<section id="${g.id}" class="outing fn-split ${g.color} ${g.weekend?'weekend':''}" aria-labelledby="title-${g.id}"><div class="outing-heading"><span class="number" aria-hidden="true">${g.number}</span><div><p class="eyebrow">${g.timing}</p><h2 id="title-${g.id}">${g.title}</h2><p class="section-desc">${g.description}</p></div><span class="group-count" id="count-${g.id}" aria-label="Completamento della sezione"></span></div><div class="outing-body fn-split-body">${g.sections.map(([title,rows],si)=>{const ps=(PHOTOS[g.id]||[])[si]||[];const card=`<div class="task-group"><h3>${title}</h3>${rows.map(r=>item(r)).join('')}</div>`;return ps.length?`<div class="fn-v-row${rowN++%2?' fn-v-rev':''}"><div class="fn-v-side">${ps.map(fig).join('')}</div>${card}</div>`:card;}).join('')}</div><div class="outing-note"><p>${g.note}</p>${g.link?`<a href="${g.link[1]}" target="_blank" rel="noopener noreferrer">${g.link[0]} ↗︎</a>`:''}</div></section>`).join('');
document.querySelector('#optional-list').innerHTML=optional.map(r=>item(r,true)).join('');
const mainIds=groups.flatMap(g=>g.sections.flatMap(s=>s[1].map(r=>r[0])));
function update(announce=false){const done=mainIds.filter(id=>checked[id]===true).length;const percent=Math.round(done/mainIds.length*100);document.querySelector('#progress-count').textContent=done;document.querySelector('#progress-total').textContent=`su ${mainIds.length} posti e momenti`;document.querySelector('#percent').textContent=percent+'%';document.querySelector('#progress').value=percent;document.querySelector('#progress').textContent=percent+'%';groups.forEach(g=>{const ids=g.sections.flatMap(s=>s[1].map(r=>r[0]));document.querySelector('#count-'+g.id).textContent=`${ids.filter(id=>checked[id]===true).length} / ${ids.length}`;});const extra=optional.filter(r=>checked[r[0]]===true).length;document.querySelector('#extra-count').textContent=`${extra} ${extra===1?'tappa facoltativa fatta':'tappe facoltative fatte'}`;document.querySelector('#save-note').textContent=storageOK?'Progressi salvati su questo dispositivo.':'Le spunte funzionano qui, ma in questo browser il salvataggio non è disponibile.';if(announce)document.querySelector('#announcement').textContent=`${done} su ${mainIds.length} voci principali completate. ${extra} tappe facoltative fatte.`;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(checked));storageOK=true;}catch{storageOK=false;}}
document.addEventListener('change',e=>{if(!e.target.matches('.task input'))return;checked[e.target.id]=e.target.checked;e.target.closest('.task').classList.toggle('completed',e.target.checked);persist();update(true);});
window.addEventListener('storage',e=>{if(e.key!==KEY)return;try{const next=JSON.parse(e.newValue||'{}');checked=next&&typeof next==='object'&&!Array.isArray(next)?next:{};}catch{checked={};}document.querySelectorAll('.task input').forEach(el=>{el.checked=checked[el.id]===true;el.closest('.task').classList.toggle('completed',el.checked);});update();});
const dialog=document.querySelector('#reset-dialog');document.querySelector('#reset').addEventListener('click',()=>dialog.showModal());document.querySelector('#cancel-reset').addEventListener('click',()=>dialog.close());document.querySelector('#confirm-reset').addEventListener('click',()=>{checked={};persist();document.querySelectorAll('.task input').forEach(el=>{el.checked=false;el.closest('.task').classList.remove('completed');});update(true);dialog.close();});
update();
